package io.github.mesmerprism.rustyquest.native_renderer;
import org.json.JSONObject;
public final class ExperimentSessionUiControlHandoffTest {
 static void require(boolean ok,String why){if(!ok)throw new AssertionError(why);}
 static final class TestOwner implements ExperimentSessionUiControlHandoff.Owner {
  long now=1000;int returns,dispatches;String outcome="";JSONObject value;Runnable callback;boolean dispatchFails;
  TestOwner()throws Exception{value=new JSONObject().put("phase","active").put("control_state","armed").put("generation",7L).put("runtime_epoch",3L).put("session_key","utc-ns-00000000000000000042").put("condition_id","condition-a").put("non_audio_profile_sha256",ExperimentSessionControlCapabilityTest.repeat("1",64)).put("activation_binding_sha256",ExperimentSessionControlCapabilityTest.repeat("2",64)).put("presentation","unfocused");}
  public JSONObject read(){return value;}public void returnVr(){returns++;}public void dispatch(JSONObject command)throws Exception{dispatches++;require(command.getString("operator_origin").equals("ui-session-v2"),"origin");if(dispatchFails)throw new Exception("unknown dispatch");}public void schedule(Runnable r,long delay){callback=r;}public long nowMs(){return now;}public long nowNs(){return now*1000000;}public void outcome(String s){outcome=s;}
 }
 static ExperimentSessionControlCapability.Fence fence(String op){return new ExperimentSessionControlCapability.Fence("", "utc-ns-00000000000000000042","condition-a",ExperimentSessionControlCapabilityTest.repeat("1",64),ExperimentSessionControlCapabilityTest.repeat("2",64),op,7,3,0,0,0);}
 public static void main(String[]a)throws Exception{
  TestOwner o=new TestOwner();ExperimentSessionUiControlHandoff h=new ExperimentSessionUiControlHandoff(o,fence("start"),"ui-original");h.run();require(o.returns==1&&o.dispatches==0,"handoff does not start");o.now+=100;o.value.put("presentation","immersive-active");o.callback.run();h.run();require(o.dispatches==1&&!h.pending()&&o.outcome.equals("native-queued-not-applied"),"one actual presentation dispatch");
  for(String key:new String[]{"generation","runtime_epoch","session_key","condition_id","non_audio_profile_sha256","activation_binding_sha256","control_state","phase"}){TestOwner bad=new TestOwner();ExperimentSessionUiControlHandoff c=new ExperimentSessionUiControlHandoff(bad,fence("start"),"ui-stale");c.run();bad.value.put(key,key.equals("generation")||key.equals("runtime_epoch")?99:key.equals("phase")?"idle":"changed");bad.value.put("presentation","immersive-active");bad.callback.run();require(bad.dispatches==0&&!c.pending(),"changed tuple denies "+key);}
  for(Object phase:new Object[]{JSONObject.NULL,"idle","closed","ACTIVE",Boolean.TRUE,7}){TestOwner bad=new TestOwner();bad.value.put("phase",phase).put("recording",true).put("presentation","immersive-active");ExperimentSessionUiControlHandoff rejected=new ExperimentSessionUiControlHandoff(bad,fence("start"),"ui-phase");rejected.run();require(bad.returns==0&&bad.dispatches==0&&!rejected.pending(),"fabricated recording cannot replace native phase "+phase);}
  TestOwner missing=new TestOwner();missing.value.remove("phase");missing.value.put("recording",true);ExperimentSessionUiControlHandoff absent=new ExperimentSessionUiControlHandoff(missing,fence("start"),"ui-missing-phase");absent.run();require(missing.returns==0&&missing.dispatches==0&&!absent.pending(),"missing phase denied");
  TestOwner authoritative=new TestOwner();authoritative.value.put("recording",false).put("presentation","immersive-active");ExperimentSessionUiControlHandoff active=new ExperimentSessionUiControlHandoff(authoritative,fence("start"),"ui-raw-phase");active.run();require(authoritative.dispatches==1,"native phase is authoritative without adapter recording");
  TestOwner receiptOwner=new TestOwner();ExperimentSessionUiCommandReceipt queued=new ExperimentSessionUiCommandReceipt(fence("start"),"ui-command");require("pending-not-applied".equals(queued.observe(receiptOwner.value)),"queued status is not applied");
  receiptOwner.value.put("operator_operation_id","ui-command").put("operator_origin","ui-session-v2").put("operator_operation_status","applied").put("control_state","running");require("applied".equals(queued.observe(receiptOwner.value)),"exact native operator receipt confirms");
  for(String key:new String[]{"generation","runtime_epoch","session_key","condition_id","non_audio_profile_sha256","activation_binding_sha256"}){JSONObject altered=new JSONObject(receiptOwner.value.toString());altered.put(key,key.equals("generation")||key.equals("runtime_epoch")?99:"changed");require("owner-changed-outcome-unknown".equals(queued.observe(altered)),"changed receipt tuple never confirms "+key);}
  for(String key:new String[]{"operator_operation_id","operator_origin","operator_operation_status","control_state","phase"}){JSONObject altered=new JSONObject(receiptOwner.value.toString());altered.put(key,"changed");require("pending-not-applied".equals(queued.observe(altered)),"mismatched effective receipt never confirms "+key);}
  receiptOwner.value.put("last_operation_id","ui-command").put("last_operation_status","rejected");require("rejected".equals(queued.observe(receiptOwner.value)),"current native rejection wins over prior applied fields");
  TestOwner timeout=new TestOwner();ExperimentSessionUiControlHandoff c=new ExperimentSessionUiControlHandoff(timeout,fence("start"),"ui-timeout");c.run();timeout.now+=5001;timeout.callback.run();require(timeout.dispatches==0&&!c.pending(),"bounded timeout no start");
  TestOwner regression=new TestOwner();c=new ExperimentSessionUiControlHandoff(regression,fence("start"),"ui-clock");regression.now--;c.run();require(regression.returns==0&&regression.dispatches==0,"clock regression denied");
  TestOwner resume=new TestOwner();resume.value.put("control_state","paused").put("presentation","immersive-active");c=new ExperimentSessionUiControlHandoff(resume,fence("resume"),"ui-resume");c.run();require(resume.dispatches==1&&resume.returns==0,"already immersive real resume");
  TestOwner failed=new TestOwner();failed.value.put("presentation","immersive-active");failed.dispatchFails=true;c=new ExperimentSessionUiControlHandoff(failed,fence("start"),"ui-failed");c.run();c.run();require(failed.dispatches==1&&!c.pending(),"unknown dispatch never replay");
  System.out.println("PASS production UI handoff exact-owner changes/real presentation/timeout/once-only dispatch controls");
 }
}
